insert into public.email_automations(id,key,name,trigger_type,is_active) values('f4122683-07c0-518b-9102-9a066771750e','course_yoga-health','Йога и здоровье','course',false) on conflict(id) do nothing;
insert into public.courses(slug,title,kind,landing_url,access_days,day_card_extra_days,webinar_extra_days,automation_id,source_hash) values('yoga-health','Йога и здоровье','course','https://zamkovoi.yoga/yoga1/',90,3,5,'f4122683-07c0-518b-9102-9a066771750e','d38920ffa36245a58ddfa3f37bcb88d5133f1c3f2b9d101afe489a3e0fdd1f0f') on conflict(slug) do update set title=excluded.title,source_hash=excluded.source_hash;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('fce16504-3e5a-58ac-a8d8-f742fc297527','f4122683-07c0-518b-9102-9a066771750e','Урок 1: Чакральная модель личности',1,0,'{Йога и здоровье} Урок 1: Чакральная модель личности','{"ru":"{Йога и здоровье} Урок 1: Чакральная модель личности"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Благодарю Вас за решение пройти курс &quot;Йога и Здоровье&quot;! Впереди у Вас длинный путь, и непростой. Мы будем работать на уровне муладхары, и если Вы не побоитесь копнуть чуть глубже физического выполнения асан, то обнаружите внутри себя огромный океан, в центре которого небольшое судно, с конфликтующей командой, и потерянным капитаном. Мы направим внимание на то, чтобы оживить капитана, навести порядок в команде, и подготовить судно к плаванию.</p><p></p><p>Расписание:</p><p></p><p>Начиная с сегодняшнего дня, каждую неделю в течение четырёх недель Вы будете получать четыре урока. Каждый раз Вам будет приходить письмо со ссылкой на урок. Время отправления писем будет такое-же, как время отправления данного письма. Если в какой-то день моё письмо не придёт, проверьте папочку &quot;Спам&quot;, а в Gmail ещё и &quot;Промоакции&quot;.</p><p></p><p>Расписание каждой недели таково:<br>- День 1: Теоретический урок<br>- День 2: Практический урок<br>- День 3: Самостоятельная практика<br>- День 4: Теоретический урок<br>- День 5: Практический урок<br>- День 6: Самостоятельная практика<br>- День 7: Самостоятельная практика</p><p></p><p>Приготовьтесь к тому, что уроки длительные - 1-2 часа, и насыщенные. Рекомендую Вам не откладывать просмотр уроков и выполнение практик. Двигайтесь в потоке расписания, и Вы получите максимальный эффект.</p><p></p><p>Вебинары и ответы на вопросы:</p><p></p><p>В процессе прохождения уроков у Вас наверняка будут возникать вопросы. Чтобы поддерживать живую обратную связь и отвечать на ваши вопросы, каждую неделю я провожу закрытые групповые консультации (вебинары). Обычно они проходят по субботам. В них принимает участие меньше людей, чем в моих прямых эфирах в Ютюбе. Поэтому есть возможность больше внимания уделить именно Вам и Вашим вопросам. Да и вопросы мы обсуждаем гораздо более глубокие и интересные. Перед началом каждого вебинара я буду отправлять письмо со ссылкой на вебинарную комнату. То есть у Вас впереди 4 вебинара. Не упускайте эту возможность, чтобы получить от данного курса максимальный эффект!</p><p></p><p>Техника безопасности:</p><p></p><p>Я забочусь о Вашем здоровье и напоминаю, что только Вы несёте ответственность за адекватность выполнения рекомендованных в данном курсе заданий (то есть асан, пранаям и медитаций) Вашим физическим возможностям и психическому состоянию. В случае необходимости, целесообразность выполнения заданий должна согласовываться с врачом. Важно понимать, что это онлайн курс, и я не могу проконтролировать состояние каждого, кто на него записывается. А люди бывают разные. У каждого есть физические и психологические особенности. Я с любовью отобрал, и предлагаю Вам максимально эффективные техники, необходимые для достижения целей данного курса. Но я не несу ответственности за последствия их применения. Пожалуйста, будьте внимательны к своему состоянию.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Желаю Вам плодотворного прохождения курса!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Благодарю Вас за решение пройти курс &quot;Йога и Здоровье&quot;! Впереди у Вас длинный путь, и непростой. Мы будем работать на уровне муладхары, и если Вы не побоитесь копнуть чуть глубже физического выполнения асан, то обнаружите внутри себя огромный океан, в центре которого небольшое судно, с конфликтующей командой, и потерянным капитаном. Мы направим внимание на то, чтобы оживить капитана, навести порядок в команде, и подготовить судно к плаванию.</p><p></p><p>Расписание:</p><p></p><p>Начиная с сегодняшнего дня, каждую неделю в течение четырёх недель Вы будете получать четыре урока. Каждый раз Вам будет приходить письмо со ссылкой на урок. Время отправления писем будет такое-же, как время отправления данного письма. Если в какой-то день моё письмо не придёт, проверьте папочку &quot;Спам&quot;, а в Gmail ещё и &quot;Промоакции&quot;.</p><p></p><p>Расписание каждой недели таково:<br>- День 1: Теоретический урок<br>- День 2: Практический урок<br>- День 3: Самостоятельная практика<br>- День 4: Теоретический урок<br>- День 5: Практический урок<br>- День 6: Самостоятельная практика<br>- День 7: Самостоятельная практика</p><p></p><p>Приготовьтесь к тому, что уроки длительные - 1-2 часа, и насыщенные. Рекомендую Вам не откладывать просмотр уроков и выполнение практик. Двигайтесь в потоке расписания, и Вы получите максимальный эффект.</p><p></p><p>Вебинары и ответы на вопросы:</p><p></p><p>В процессе прохождения уроков у Вас наверняка будут возникать вопросы. Чтобы поддерживать живую обратную связь и отвечать на ваши вопросы, каждую неделю я провожу закрытые групповые консультации (вебинары). Обычно они проходят по субботам. В них принимает участие меньше людей, чем в моих прямых эфирах в Ютюбе. Поэтому есть возможность больше внимания уделить именно Вам и Вашим вопросам. Да и вопросы мы обсуждаем гораздо более глубокие и интересные. Перед началом каждого вебинара я буду отправлять письмо со ссылкой на вебинарную комнату. То есть у Вас впереди 4 вебинара. Не упускайте эту возможность, чтобы получить от данного курса максимальный эффект!</p><p></p><p>Техника безопасности:</p><p></p><p>Я забочусь о Вашем здоровье и напоминаю, что только Вы несёте ответственность за адекватность выполнения рекомендованных в данном курсе заданий (то есть асан, пранаям и медитаций) Вашим физическим возможностям и психическому состоянию. В случае необходимости, целесообразность выполнения заданий должна согласовываться с врачом. Важно понимать, что это онлайн курс, и я не могу проконтролировать состояние каждого, кто на него записывается. А люди бывают разные. У каждого есть физические и психологические особенности. Я с любовью отобрал, и предлагаю Вам максимально эффективные техники, необходимые для достижения целей данного курса. Но я не несу ответственности за последствия их применения. Пожалуйста, будьте внимательны к своему состоянию.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Желаю Вам плодотворного прохождения курса!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-01-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Благодарю Вас за решение пройти курс &quot;Йога и Здоровье&quot;! Впереди у Вас длинный путь, и непростой. Мы будем работать на уровне муладхары, и если Вы не побоитесь копнуть чуть глубже физического выполнения асан, то обнаружите внутри себя огромный океан, в центре которого небольшое судно, с конфликтующей командой, и потерянным капитаном. Мы направим внимание на то, чтобы оживить капитана, навести порядок в команде, и подготовить судно к плаванию.</p><p></p><p>Расписание:</p><p></p><p>Начиная с сегодняшнего дня, каждую неделю в течение четырёх недель Вы будете получать четыре урока. Каждый раз Вам будет приходить письмо со ссылкой на урок. Время отправления писем будет такое-же, как время отправления данного письма. Если в какой-то день моё письмо не придёт, проверьте папочку &quot;Спам&quot;, а в Gmail ещё и &quot;Промоакции&quot;.</p><p></p><p>Расписание каждой недели таково:<br>- День 1: Теоретический урок<br>- День 2: Практический урок<br>- День 3: Самостоятельная практика<br>- День 4: Теоретический урок<br>- День 5: Практический урок<br>- День 6: Самостоятельная практика<br>- День 7: Самостоятельная практика</p><p></p><p>Приготовьтесь к тому, что уроки длительные - 1-2 часа, и насыщенные. Рекомендую Вам не откладывать просмотр уроков и выполнение практик. Двигайтесь в потоке расписания, и Вы получите максимальный эффект.</p><p></p><p>Вебинары и ответы на вопросы:</p><p></p><p>В процессе прохождения уроков у Вас наверняка будут возникать вопросы. Чтобы поддерживать живую обратную связь и отвечать на ваши вопросы, каждую неделю я провожу закрытые групповые консультации (вебинары). Обычно они проходят по субботам. В них принимает участие меньше людей, чем в моих прямых эфирах в Ютюбе. Поэтому есть возможность больше внимания уделить именно Вам и Вашим вопросам. Да и вопросы мы обсуждаем гораздо более глубокие и интересные. Перед началом каждого вебинара я буду отправлять письмо со ссылкой на вебинарную комнату. То есть у Вас впереди 4 вебинара. Не упускайте эту возможность, чтобы получить от данного курса максимальный эффект!</p><p></p><p>Техника безопасности:</p><p></p><p>Я забочусь о Вашем здоровье и напоминаю, что только Вы несёте ответственность за адекватность выполнения рекомендованных в данном курсе заданий (то есть асан, пранаям и медитаций) Вашим физическим возможностям и психическому состоянию. В случае необходимости, целесообразность выполнения заданий должна согласовываться с врачом. Важно понимать, что это онлайн курс, и я не могу проконтролировать состояние каждого, кто на него записывается. А люди бывают разные. У каждого есть физические и психологические особенности. Я с любовью отобрал, и предлагаю Вам максимально эффективные техники, необходимые для достижения целей данного курса. Но я не несу ответственности за последствия их применения. Пожалуйста, будьте внимательны к своему состоянию.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Желаю Вам плодотворного прохождения курса!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-01','yoga-health',1,0,'Урок 1: Чакральная модель личности','[{"type":"text","markdown":"Предлагаю не растягивать резину, и сразу нырнуть в святая-святых йоги - в изучение чакр. О чакрах много говорят, много пишут. И фраза \"открыть чакры\" стала притчей во языцех, высмеивающей слепую эзотерику. Между тем, чтобы общаться на языке йоги, необходимо освоить метафоры чакр. Причем, освоить не головой, а на уровне ощущений. И в данном уроке мы займёмся именно этим."},{"type":"video","vimeoId":"307424886"},{"type":"text","markdown":"Все уроки этого курса я проводил в виде онлайн трансляций. Поэтому вы увидите, что иногда я выхожу из кадра, чтобы проверить продолжается ли трансляция. Не удивляйтесь этому. К сожалению (или к счастью) в полноценные вебинары эти трансляции не переросли так как на ярком солнце монитор казался чёрным и мне было сложно следить за чатом.\n\nКстати, уроки я проводил утром - в 7:00 МСК. Рекомендую и вам проходить каждый урок утром, чтобы заряжаться энергией, идеями, инсайтами, а в течение дня закреплять их на практике. Это значительно повышает эффективность прохождения курса. Если же смотреть уроки вечером перед сном, то за ночь все самое ценное будет уходить в подсознание. И следующий день с точки зрения целей данного курса будет далеко не столь продуктивен.\n\nТак как уроки длинные, рекомендую вам делать заметки в блокноте. Вы можете либо записывать ценные идеи, либо указывать время в видеозаписи, когда прозвучала интересная вам мысль. А чтобы вам было легче ориентироваться в видео, под большинством уроков я вставил тайминг.\n\nТайминг:\n00:00 Введение\n18:53 Ритуал постановки намерения на курс\n36:46 Чакральная модель личности\n42:40 Что значит сила/слабость чакры\n45:00 Проявления сильной муладхары.\n\nЗадание:\nАнализируйте встречных людей, определяя их сильные чакры."}]'::jsonb,'fce16504-3e5a-58ac-a8d8-f742fc297527') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('ee74151f-f528-5662-a155-7a4d704fe78d','f4122683-07c0-518b-9102-9a066771750e','Урок 2: Пробуждение организма, включение программы оздоравливания',2,0,'{Йога и здоровье} Урок 2: Пробуждение организма и запуск самооздоравливания','{"ru":"{Йога и здоровье} Урок 2: Пробуждение организма и запуск самооздоравливания"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Наша цель - как можно скорей включить свое тело, начать слышать его голос, и запустить программу самооздоравливания. Делается это очень просто - регулярным выполнением специальных упражнений. Именно их я хочу Вам сегодня показать.</p><p></p><p>Эти упражения очень важны также, чтобы подготовить тело к практике йоги. Без шуток! Это очень важно!!! Травмы в йоге происходят очень часто. На этой неделе я присоединился к вечерним занятиям группы, приехавшей в Гокарну в так называемый йога-тур. И один человек из десяти уже не может ходить - получил межпозвоночную грыжу. Вот так человек оздоровился. И это легко понять. Сидел он в офисе, дважды в неделю ходил на йогу. А тут вдруг два занятия в день. Тело немного продержалось в этом темпе, и сломалось. Поэтому в данном курсе мы входим в практику асан неспеша. Но все-равно критически быстро. И чтобы поддержать своё тело, как минимум на протяжении всего этого курса, обязательно ежедневно выполняйте упражнения которые я показываю в данном уроке.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Наша цель - как можно скорей включить свое тело, начать слышать его голос, и запустить программу самооздоравливания. Делается это очень просто - регулярным выполнением специальных упражнений. Именно их я хочу Вам сегодня показать.</p><p></p><p>Эти упражения очень важны также, чтобы подготовить тело к практике йоги. Без шуток! Это очень важно!!! Травмы в йоге происходят очень часто. На этой неделе я присоединился к вечерним занятиям группы, приехавшей в Гокарну в так называемый йога-тур. И один человек из десяти уже не может ходить - получил межпозвоночную грыжу. Вот так человек оздоровился. И это легко понять. Сидел он в офисе, дважды в неделю ходил на йогу. А тут вдруг два занятия в день. Тело немного продержалось в этом темпе, и сломалось. Поэтому в данном курсе мы входим в практику асан неспеша. Но все-равно критически быстро. И чтобы поддержать своё тело, как минимум на протяжении всего этого курса, обязательно ежедневно выполняйте упражнения которые я показываю в данном уроке.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-02-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Наша цель - как можно скорей включить свое тело, начать слышать его голос, и запустить программу самооздоравливания. Делается это очень просто - регулярным выполнением специальных упражнений. Именно их я хочу Вам сегодня показать.</p><p></p><p>Эти упражения очень важны также, чтобы подготовить тело к практике йоги. Без шуток! Это очень важно!!! Травмы в йоге происходят очень часто. На этой неделе я присоединился к вечерним занятиям группы, приехавшей в Гокарну в так называемый йога-тур. И один человек из десяти уже не может ходить - получил межпозвоночную грыжу. Вот так человек оздоровился. И это легко понять. Сидел он в офисе, дважды в неделю ходил на йогу. А тут вдруг два занятия в день. Тело немного продержалось в этом темпе, и сломалось. Поэтому в данном курсе мы входим в практику асан неспеша. Но все-равно критически быстро. И чтобы поддержать своё тело, как минимум на протяжении всего этого курса, обязательно ежедневно выполняйте упражнения которые я показываю в данном уроке.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-02','yoga-health',2,1,'Урок 2: Пробуждение организма, включение программы оздоравливания','[{"type":"video","vimeoId":"1099983495"},{"type":"text","markdown":"Тайминг:\n05:45 Пробуждение организма\n22:00 Суставная гимнастика\n56:00 Прохлопывание\n1:03:03 Пассивная растяжка\n\nЗадания:\n1. Хотя-бы в течение одной недели ежедневно выполняйте предложенные техники пробуждения организма, чтобы закрепить данный навык.\n\n2. Каждый день утром и вечером в течение курса выполняйте суставную гимнастику, чтобы подготовить тело к выполнению асан\n\n3. Хотя бы в течение одной недели выполняйте прохлопывание, чтобы освоить эту практику\n\n4. В течение всего курса, ежедневно 10-15 минут практикуйте осознанную ходьбу, чтобы запустить процесс оздоравливания тазобедренных суставов, а также почувствовать как оживает тело, и начинает действовать независимо от голоса разума\n\n5. В течение всего курса ежедневно практикуйте пассивную растяжку, чтобы гармонизировать сферу муладхары."}]'::jsonb,'ee74151f-f528-5662-a155-7a4d704fe78d') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('3adbd858-55c9-5d43-a5a4-8b841006d791','f4122683-07c0-518b-9102-9a066771750e','Урок 3: Чакральные кризисы, как ступени на пути развития',3,0,'{Йога и здоровье} Урок 3: Чакральные кризисы, как ступени на пути развития','{"ru":"{Йога и здоровье} Урок 3: Чакральные кризисы, как ступени на пути развития"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>В процессе жизни мы регулярно проходим различные личностные кризисы. Явление неприятное, которое может затянуться на долгие годя. Именно в этот момент многие люди приходят в йогу. Почему?</p><p></p><p>Потому что йога содержит знание и технику прохождения личностных кризисов. И сегодняшний урок посвящён именно ей.</p><p></p><p>Если сейчас у Вас непростой период жизни, его можно рассматривать как тот или иной кризис. И пройдя данный урок Вам станет понятно где в тёмной комнате.... нет, не кошка, и не иголка... а дверь :). Далее нужно будет начать движение в её направлении.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Нового знания!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>В процессе жизни мы регулярно проходим различные личностные кризисы. Явление неприятное, которое может затянуться на долгие годя. Именно в этот момент многие люди приходят в йогу. Почему?</p><p></p><p>Потому что йога содержит знание и технику прохождения личностных кризисов. И сегодняшний урок посвящён именно ей.</p><p></p><p>Если сейчас у Вас непростой период жизни, его можно рассматривать как тот или иной кризис. И пройдя данный урок Вам станет понятно где в тёмной комнате.... нет, не кошка, и не иголка... а дверь :). Далее нужно будет начать движение в её направлении.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Нового знания!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-03-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>В процессе жизни мы регулярно проходим различные личностные кризисы. Явление неприятное, которое может затянуться на долгие годя. Именно в этот момент многие люди приходят в йогу. Почему?</p><p></p><p>Потому что йога содержит знание и технику прохождения личностных кризисов. И сегодняшний урок посвящён именно ей.</p><p></p><p>Если сейчас у Вас непростой период жизни, его можно рассматривать как тот или иной кризис. И пройдя данный урок Вам станет понятно где в тёмной комнате.... нет, не кошка, и не иголка... а дверь :). Далее нужно будет начать движение в её направлении.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Нового знания!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-03','yoga-health',3,2,'Урок 3: Чакральные кризисы, как ступени на пути развития','[{"type":"text","markdown":"В этом уроке мы рассмотрим чакральную модель развития. В результате у Вас сложится понимание природы различных личностных кризисов, и получите ценные ключи к переходу на следующий уровень."},{"type":"video","vimeoId":"1099984641"},{"type":"text","markdown":"Тайминг:\n6:45 Пирамида Маслоу и чакральные потребности\n10:50 Муладхара\n18:35 Переход на уровень свадхистханы\n23:50 Переход на уровень манипуры\n31:30 Переход на уровень анахаты\n41:35 Переход на уровень вишудхи\n47:20 Переход на уровень аджны\n51:55 Переход на уровень сахасрары\n55:55 Сильные чакры и положение на лестнице развития\n1:00:26 Ответ на вопрос\n\nЗадания:\n1. Проанализируйте сферу муладхары в своей жизни - насколько она гармонична, насколько она для вас актуальна, и что нуждается в улучшении.\n\n2. Определите свою сильную чакру.\n\n3. Разберитесь какой уровень развития (в чакральном контексте) Вы сейчас проходите, и насколько гармонично устроены предыдущие уровни.\n\nЧтобы лучше проникнуться энергиями места, я предлагаю Вам посмотреть небольшое видео с легендой об озере Коти Тиртха, на котором прошёл этот урок. Заодно Вы узнаете как относиться к легендам и мифам. А это важный шаг на пути волшебника!"},{"type":"video","vimeoId":"1099985558"}]'::jsonb,'3adbd858-55c9-5d43-a5a4-8b841006d791') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('93895923-3ad1-569c-b39a-11e6c2b1024a','f4122683-07c0-518b-9102-9a066771750e','Урок 4: Практика на открытие муладхара-чакры',4,0,'{Йога и здоровье} Урок 4: Практика на осознание энергии муладхара-чакры','{"ru":"{Йога и здоровье} Урок 4: Практика на осознание энергии муладхара-чакры"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня Вас ожидает интереснейший практический урок, который поможет почувствовать целостное состояние муладхары.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня Вас ожидает интереснейший практический урок, который поможет почувствовать целостное состояние муладхары.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-04-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня Вас ожидает интереснейший практический урок, который поможет почувствовать целостное состояние муладхары.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-04','yoga-health',4,1,'Урок 4: Практика на открытие муладхара-чакры','[{"type":"text","markdown":"Сегодня Вас ожидает практика на открытие муладхары. Выполнив эту практику, вы почувствуете состояние целостной муладхары, и сможете поставить исполняемое намерение на здоровье и самоисцеление. Мощнейшая практика! Если первые два урока мы двигались от головы, и Вы поняли роль муладхары в жизни, и в преодолении личностных кризисов. То этот урок поможет Вам на уровне внутренних ощущений понять что же такое муладхара, и какими внутренними состояниями она управляет."},{"type":"video","vimeoId":"1099986102"},{"type":"text","markdown":"Техника:\n\n1 этап. 15 минут вращение по часовой стрелке. Со вдохом делаем мулабандху и со всасывающим ощущением набираем энергию сверху, опуская её до муладхары. На выдохе отпускаем мулабандху и направляем энергию вниз.\n\n2 этап. 15 минут вращение против часовой стрелки. На вдохе отпускаем мулабандху и набираем энергию снизу, а на выдохе делаем мулабандху и толкаем энергию вверх.\n\n3 этап. 15 медитация. Расслабленное, естественное дыхание, с ощущением что вдох и выдох происходят через муладхару.\n\nОтветы на поступившие вопросы:"},{"type":"video","vimeoId":"1099986456"},{"type":"text","markdown":"Задание к уроку:\n\nВ ближайшие дни несколько раз выполните практику данного урока, чтобы овладеть навыком сознательного наполнения муладхары энергией. А также продолжайте применять техники, пройденные на уроке 2. Далее мы перейдем к освоению асан, и эти два практических урока подготовят Вас к следующим шагам."}]'::jsonb,'93895923-3ad1-569c-b39a-11e6c2b1024a') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('8545f986-c4df-5996-980c-586da45c887b','f4122683-07c0-518b-9102-9a066771750e','Урок 5: Узнайте и присвойте ценности, которые скрывают ваши страхи',5,0,'{Йога и здоровье} Урок 5: Узнайте и присвойте ценности, которые скрывают ваши страхи','{"ru":"{Йога и здоровье} Урок 5: Узнайте и присвойте ценности, которые скрывают ваши страхи"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время встретиться со своими страхами. И чтобы эта встреча прошла конструктивно, и подвела Вас к новому занию, пройдите данный урок.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Бесстрашия!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время встретиться со своими страхами. И чтобы эта встреча прошла конструктивно, и подвела Вас к новому занию, пройдите данный урок.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Бесстрашия!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-05-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время встретиться со своими страхами. И чтобы эта встреча прошла конструктивно, и подвела Вас к новому занию, пройдите данный урок.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Бесстрашия!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-05','yoga-health',5,3,'Урок 5: Узнайте и присвойте ценности, которые скрывают ваши страхи','[{"type":"text","markdown":"Родившись свободными, в зрелом возрасте мы вдруг вынуждены признать, что нами управляют различные страхи. Любопытно, что от своих страхов невозможно убежать. А значит страхи находятся внутри нас, или они каким-то образом с нами связаны. А раз так, значит техниками йоги мы можем с ними работать. И в этом уроке мы приоткроем дверцу. Мы рассмотрим что же такое то, что мы называем Страхом. И выполним практику, которая даст Вам эзотерическую подключку к работе со страхами."},{"type":"video","vimeoId":"1099987411"},{"type":"text","markdown":"Задание:\nСамостоятельно повторите предложенную в уроке практику как минимум три раза. Таким образом Вы проработаете три своих страха, и откроете в себе три ценнейших состояния. Не пытайтесь анализировать происходящее. Просто, выполняйте практику, и получайте её плоды!"}]'::jsonb,'8545f986-c4df-5996-980c-586da45c887b') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('76c004cd-9c14-537b-b764-ca57e3299bf3','f4122683-07c0-518b-9102-9a066771750e','Урок 6: Изучение эффекта каждой асаны, входящей в комплекс Сурья Намаскар',6,0,'{Йога и здоровье} Урок 6: Изучение эффекта каждой асаны, входящей в комплекс Сурья Намаскар','{"ru":"{Йога и здоровье} Урок 6: Изучение эффекта каждой асаны, входящей в комплекс Сурья Намаскар"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня на практическом уроке мы начнём осваивать асаны йоги. Конечно, асаны можно рассматривать исключительно на физиологическом уровне, и получать оздоравливающий эффект. Но я предлагаю открыться эзотерике. Выполняйте асаны, удерживая внимание на какой-либо задаче (например, на осваивании ресурса, открывшегося в результате предыдущей практики), и Мироздание (Бог, Ваш род, коллективное бессознательное...) будет двавть Вам подсказки и ключи там, где Вы не ожидаете - в случайном стечении обстоятельств, в чьих-то словах, в возникших в медитации образах...</p><p></p><p>И данный курс работает именно так на уровне муладхары. Проходя его, Вы можете ощутить желание (или заметить внешние толчки) к тому чтобы привести в порядок подзависшие дела, заняться мелочами, которые долго откладывали, пройти медицинское обследование, провести ремонт дома, навести порядок в гардеробе или на жестком диске компьютера, и т.д... Будьте осознанны и открыты. Используйте энергию своих желаний и внешних толчков. Это всё Вам на пользу!</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня на практическом уроке мы начнём осваивать асаны йоги. Конечно, асаны можно рассматривать исключительно на физиологическом уровне, и получать оздоравливающий эффект. Но я предлагаю открыться эзотерике. Выполняйте асаны, удерживая внимание на какой-либо задаче (например, на осваивании ресурса, открывшегося в результате предыдущей практики), и Мироздание (Бог, Ваш род, коллективное бессознательное...) будет двавть Вам подсказки и ключи там, где Вы не ожидаете - в случайном стечении обстоятельств, в чьих-то словах, в возникших в медитации образах...</p><p></p><p>И данный курс работает именно так на уровне муладхары. Проходя его, Вы можете ощутить желание (или заметить внешние толчки) к тому чтобы привести в порядок подзависшие дела, заняться мелочами, которые долго откладывали, пройти медицинское обследование, провести ремонт дома, навести порядок в гардеробе или на жестком диске компьютера, и т.д... Будьте осознанны и открыты. Используйте энергию своих желаний и внешних толчков. Это всё Вам на пользу!</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-06-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня на практическом уроке мы начнём осваивать асаны йоги. Конечно, асаны можно рассматривать исключительно на физиологическом уровне, и получать оздоравливающий эффект. Но я предлагаю открыться эзотерике. Выполняйте асаны, удерживая внимание на какой-либо задаче (например, на осваивании ресурса, открывшегося в результате предыдущей практики), и Мироздание (Бог, Ваш род, коллективное бессознательное...) будет двавть Вам подсказки и ключи там, где Вы не ожидаете - в случайном стечении обстоятельств, в чьих-то словах, в возникших в медитации образах...</p><p></p><p>И данный курс работает именно так на уровне муладхары. Проходя его, Вы можете ощутить желание (или заметить внешние толчки) к тому чтобы привести в порядок подзависшие дела, заняться мелочами, которые долго откладывали, пройти медицинское обследование, провести ремонт дома, навести порядок в гардеробе или на жестком диске компьютера, и т.д... Будьте осознанны и открыты. Используйте энергию своих желаний и внешних толчков. Это всё Вам на пользу!</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-06','yoga-health',6,1,'Урок 6: Изучение эффекта каждой асаны, входящей в комплекс Сурья Намаскар','[{"type":"text","markdown":"Самый известный комплекс асан - это, безусловно, Сурья Намаскар (приветствие Солнца). Большинство людей, утвердившихся в практике йоги, именно с него начинают свой день. В данном уроке мы изучим асаны, входящие в его состав. Урок длинный и содержательный. Освоив его, Вы не только узнаете технику выполнения этих асан, но и получите к каждой из них важные энергетические ключи. Сам комплекс Сурья Намаскар мы будем осваивать на следующем уроке. А сейчас важно максимально прочувствовать отдельные асаны."},{"type":"video","vimeoId":"1099987643"},{"type":"text","markdown":"Тайминг:\n04:43 Что такое асана\n25:00 Пранаманасана (поза молящегося)\n38:46 Тадасана (поза горы)\n39:40 Урдхва Хастасана (вытягивание вверх)\n45:34 Уттанасана (наклон)\n56:26 Ашва Санчаланасана (поза наездника)\n01:01:20 Принципиально разные результаты асан на наклон и асан на прогиб (дающая и принимающая функция чакр)\n01:02:22  Отличие Ашва Санчаланасаны от других асан на прогиб (отдельная проработка правой и левой сторон)\n01:05:39 Чатуранга Дандасана (планка). Кстити, рекодное время планки на локтях - чуть более 8 часов!\n01:10:37 Баласана (поза ребёнка)\n01:13:30 Традиционная компенсация вишудхой дырявой анахаты\n01:21:19 Уттана Шишасана (поза щенка)\n01:24:29 О других асанах, прорабатывающих грудной отдел позвоночника\n01:27:13 Бхудхангасана (поза кобры) и Урдхва Муква Шванасана(поза собаки мордой вверх)\n01:31:08 Адхо Мукха Шванасана (поза собаки мордой вниз)\n01:37:52 Что даёт освоение этих асан\n01:40:22 Почему новичкам \"везёт\"\n01:45:36 Ответ на вопрос о причине депрессивного состояния после медитации\n\nЗадание:\nДо нашего следующего практического урока хотя бы один раз выполните каждую из этих асан, чтобы прочувствовать её состояние, и освоить технику."}]'::jsonb,'76c004cd-9c14-537b-b764-ca57e3299bf3') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('ec86e86d-c06b-5223-8b44-d0ea858c2204','f4122683-07c0-518b-9102-9a066771750e','Урок 7: Психосоматика, и техника исцеления йогой',7,0,'{Йога и здоровье} Урок 7: Психосоматика, и логика исцеления йогой','{"ru":"{Йога и здоровье} Урок 7: Психосоматика, и логика исцеления йогой"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Так почему же йога работает? Вы узнаете это, пройдя данный урок.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Так почему же йога работает? Вы узнаете это, пройдя данный урок.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-07-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Так почему же йога работает? Вы узнаете это, пройдя данный урок.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-07','yoga-health',7,2,'Урок 7: Психосоматика, и техника исцеления йогой','[{"type":"text","markdown":"Психосоматика - интереснейшее направление на стыке психологии и медицины. Она наводит мосты между тем, как Вы воспринимаете мир, и Вашим телом. С точки зрения психосоматики каждое заболевание является следствием деструктивной психологической реакции. В данном уроке мы рассмотрим основы психосоматики, и воспользуемся ими для определения своей сильной чакры. Благодаря этому Вы узнаете своё призвание в этой жизни (по крайней мере в каком направлении двигаться к счастью), научитесь эффективно коммуницировать с людьми, и замкнёте логическую цепочку понимания предыдущих уроков. Вы разберётесь как работает йога, что происходит при выполнении асан, и почему йога исцеляет."},{"type":"video","vimeoId":"1099987922"},{"type":"text","markdown":"Задания к уроку:\n\n1. Проанализируйте своё тело, и определите свои сильные чакры\n\n2. Найдите в теле боли и заболевания (желательно то, что болит именно сейчас)\n\n3. Методом анализа определите какая ценность спрятана за этой болью\n\n4. Определите какой страх стоит на пути к этой ценности?\n\n5. Выполните практику освобождения от этого страха"}]'::jsonb,'ec86e86d-c06b-5223-8b44-d0ea858c2204') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('886745bd-03fe-5c61-a2e7-e0d2523ae3d7','f4122683-07c0-518b-9102-9a066771750e','Урок 8: Волшебство комплексов асан, и глубинные ключи к Сурья Намаскар',8,0,'{Йога и здоровье} Урок 8: Волшебство комплексов асан, и глубинные ключи к Сурья Намаскар','{"ru":"{Йога и здоровье} Урок 8: Волшебство комплексов асан, и глубинные ключи к Сурья Намаскар"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня на практическом занятии мы освоим выполнение комплекса приветствия Солнца - Сурья Намаскар.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня на практическом занятии мы освоим выполнение комплекса приветствия Солнца - Сурья Намаскар.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-08-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня на практическом занятии мы освоим выполнение комплекса приветствия Солнца - Сурья Намаскар.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-08','yoga-health',8,1,'Урок 8: Волшебство комплексов асан, и глубинные ключи к Сурья Намаскар','[{"type":"text","markdown":"Этот урок посвящён освоению комплекса Сурья Намаскар. Это известнейший комплекс, который каждое утро выполняют тысячи людей, практикующих йогу. Переводится он как \"Приветствие Солнца\". Пройдя этот урок Вы узнаете назначение данного комплекса, получите ценные энергетические ключи, и освоите важные нюансы. А также мы изучим специальную «муладхарную» версию Сурья Намаскар, которая направлена на гармонизацию здоровья на физическом и событийно-психологическом уровне."},{"type":"video","vimeoId":"1099988870"},{"type":"text","markdown":"Тайминг:\n0:56 - Сурья Намаскар, как духовная сущность\n4:45 Динамика в Сурья Намаскар\n5:58 Об идеях, посещающих во время выполнения Сурья Намаскар\n8:48 В каком состоянии выполняется Сурья Намаскар\n9:20 Гуны и эффективность практики йоги в различное время суток\n13:54 Роль муладхары в структурировании пространства для практики йоги\n15:00 Обращение к Солнцу в Сурья Намаскар\n17:50 Круги энергии при выполнении Сурья Намаскар\n19:28 Прокачка в Сурья Намаскар энергией сильной или проблемной чакры\n22:30 Прокачка социальными энергиями в Сурья Намаскар\n25:58 Прокачка энергиеё муладхары\n22:57 Повторение практики пробуждения организма\n34:49 Суставная гимнастика\n42:20 Техника выполнения Сурья Намаскар\n46:28 Разминочный круг\n55:21 Круг с прокачкой Солнечной энергией\n59:09 Техника Сурья Намаскар с прокачкой муладхарной энергией\n1:12:14 Задание к уроку\n1:15:19 Посвящение заслуг\n\nОтветы на вопросы:"},{"type":"video","vimeoId":"1100113398"},{"type":"text","markdown":"Задания к уроку:\n\n1. Сегодня выполните ещё хотя бы 6 кругов Сурья Намаскар\n\n2. В течение этого курса каждое утро выполняйте Сурья Намаскар"}]'::jsonb,'886745bd-03fe-5c61-a2e7-e0d2523ae3d7') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('3297e123-6140-59b0-aca2-ab074c149276','f4122683-07c0-518b-9102-9a066771750e','Урок 9: Путь йоги согласно Патанджали, и законы гармоничного взаимодействия с миром',9,0,'{Йога и здоровье} Урок 9: Путь йоги согласно Патанджали, и законы гармоничного взаимодействия с миром','{"ru":"{Йога и здоровье} Урок 9: Путь йоги согласно Патанджали, и законы гармоничного взаимодействия с миром"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Многие учителя понимают йогу по-своему. В этом уроке мы рассмотрим структуру йоги, как она описана в Йога-сутрах Патанджали.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Многие учителя понимают йогу по-своему. В этом уроке мы рассмотрим структуру йоги, как она описана в Йога-сутрах Патанджали.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-09-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Многие учителя понимают йогу по-своему. В этом уроке мы рассмотрим структуру йоги, как она описана в Йога-сутрах Патанджали.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здоровья!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-09','yoga-health',9,3,'Урок 9: Путь йоги согласно Патанджали, и законы гармоничного взаимодействия с миром','[{"type":"text","markdown":"Пройдя этот урок у Вас сложится цельная картина йоги как системы духовных практик. Урок содержит много практик и примеров, позволяющих наполнить содержанием загадочные фразы древних текстов Йога сутр Патанджали, раскрывающих философию йоги. Особое внимание в этом уроке я обратил на первые две ступени йоги, называемые Яма и Нияма. И разобрал принципы этих ступеней как законы гармоничного взаимодействия с миром. Выполнение этих законов прекращает оттоки энергии, и отражается как на уровне нашего тела, так и на уровне происходящих с нами событий. Поэтому это первые, и базовые уровни йоги."},{"type":"video","vimeoId":"1099989660"},{"type":"text","markdown":"Тайминг:\n01:57 Постановка намерения\n11:35 О йога сутрах\n15:28 Восемь ступеней йоги\n16:06 Самадхи\n17:50 Дхьяна\n18:09 Дхарана\n22:50 Пратьяхара\n28:16 Пранаяма\n28:51 Техника Капалабхати\n40:31 Асаны\n46:27 Нияма\n48:31 Шауча\n52:23 Сантоша\n54:29 Тапас\n01:02:00 Свадхъяя\n01:05:42 Ишвара-пранидхана\n01:14:48 Яма\n01:15:46 Ахимса\n01:23:49 Сатья\n01:31:41 Астейя\n01:35:44 Брахмачарья\n01:40:05 Апариграха\n01:47:50 Задание к уроку\n\nЗадание:\n1. Самостоятельно повторите практики, которые мы выполняли в этом уроке\n\n2. Перечислите по памяти все пять принципов ямы и пять принципов ниямы.\n\n3. Проанализируйте в чём выражается негармоничность Ваших проявлений по первому принципу ямы и по первому принципу ниямы, которые Вы вспомнили.\n\n4. Аналогично с предыдущим пунктом, проанализируйте в чём выражается негармоничность Ваших проявлений по тем принципам ямы и ниямы, которые вылетели из Вашей памяти.\n\n5. Примите все выписанные нарушения как направления дальнейшей работы над собой."}]'::jsonb,'3297e123-6140-59b0-aca2-ab074c149276') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('23694751-9930-5b5a-a3f9-9d3c342fbcc6','f4122683-07c0-518b-9102-9a066771750e','Урок 10: Комплекс асан на растяжку, и техника безопасности при выполнении асан',10,0,'{Йога и здоровье} Урок 10: Комплекс асан на растяжку, и техника безопасности при выполнении асан','{"ru":"{Йога и здоровье} Урок 10: Комплекс асан на растяжку, и техника безопасности при выполнении асан"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Надеюсь, Вы уже впустили Сурья Намаскар в свою жизнь. Сегодня мы закрепим то, что проходили ранее, а также освоим новый комплекс асан.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Надеюсь, Вы уже впустили Сурья Намаскар в свою жизнь. Сегодня мы закрепим то, что проходили ранее, а также освоим новый комплекс асан.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-10-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Надеюсь, Вы уже впустили Сурья Намаскар в свою жизнь. Сегодня мы закрепим то, что проходили ранее, а также освоим новый комплекс асан.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-10','yoga-health',10,1,'Урок 10: Комплекс асан на растяжку, и техника безопасности при выполнении асан','[{"type":"text","markdown":"В этом уроке мы рассмотрим главные правила техники безопасности при выполнении асан. После чего закрепим технику пробуждения организма, суставную гимнастику, и Сурья Намаскар. Вслед за чем выполним комплекс асан на растяжку передней и задней стороны ног, и повышение гибкости области тазобедренных суставов."},{"type":"video","vimeoId":"1099990332"},{"type":"text","markdown":"Тайминг:\n08:16 Ответ на вопрос о йоге при межпозвоночных грыжах\n11:00 Калечащие гиперкомпенсации\n12:13 Как делать Бхуджангасану\n18:14 Правило четырёхугольника\n22:33 Разогрев с намерением повысить гибкость\n23:18 Не переступайте болевой порог\n24:06 Конструктивный и деструктивный стресс\n25:39 Не кушайте перед практикой йоги\n26:17 Позитивный настрой и метафора оздоравления\n31:52 Об использовании приспособлений для асан\n33:42 Дополняйте растяжку силовыми асанами\n36:40 Пробуждение организма с самомассажем\n43:41 Суставная гимнастика\n54:42 Сурья Намаскар\n01:16:15 Сжигание излишков\n01:17:42 Комплекс асан\n\nОтвет на вопрос:"},{"type":"video","vimeoId":"1099990731"},{"type":"text","markdown":"Задание к уроку:\n\nВыполняйте этот комплекс ежедневно, пока на одном из следующих уроков курса мы не освоим другой комплекс."}]'::jsonb,'23694751-9930-5b5a-a3f9-9d3c342fbcc6') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('2115100c-244b-520a-ae14-a9413fa6bf63','f4122683-07c0-518b-9102-9a066771750e','Урок 11: Методики очищения организма как простейший путь к здоровью',11,0,'{Йога и здоровье} Урок 11: Методики очищения организма как простейший путь к здоровью','{"ru":"{Йога и здоровье} Урок 11: Методики очищения организма как простейший путь к здоровью"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Самый очевидный способ изменить свою жизнь - изменить своё тело. При этом начать лучше всего с его очищения. Мы накопили очень много мусора, и пока он находится в нас, нам сложно найти место для чего-нибудь нового и здорового.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Самый очевидный способ изменить свою жизнь - изменить своё тело. При этом начать лучше всего с его очищения. Мы накопили очень много мусора, и пока он находится в нас, нам сложно найти место для чего-нибудь нового и здорового.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-11-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Самый очевидный способ изменить свою жизнь - изменить своё тело. При этом начать лучше всего с его очищения. Мы накопили очень много мусора, и пока он находится в нас, нам сложно найти место для чего-нибудь нового и здорового.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-11','yoga-health',11,2,'Урок 11: Методики очищения организма как простейший путь к здоровью','[{"type":"text","markdown":"Так кто Вы - жаворонок или сова? А если подумать? :) Сегодня мы рассмотрим утренние ритуалы, которые очищают, оздоравливают, и наполняют энергией на весь день. Также мы посмотрим на наше лето, как на симбиотический организм, и эта точка зрения даёт логичные ответы на многие загадочные вопросы (например, сколько времени необходимо для закладывания привычки, почему у меня определённые предпочтения в питании, и т.д.). А ещё я расскажу о правилах здорового питания, и о простейших голоданиях - 24 часа, 36 часов, и 3 дня."},{"type":"video","vimeoId":"1099991461"},{"type":"text","markdown":"Тайминг:\n03:27 Ритуал приветствия\n07:52 Пример из личного опыта отключения деструктивной программы с помощью голодания\n17:06 Каков срок закладывания новой привычки\n17:56 Циклы регенерации физического тела\n22:48 Чистки\n23:55 Утренние ритуалы\n24:13 Во сколько просыпаться\n27:32 Значение позитивного настроя во время чисток\n29:24 Приветствие\n29:36 Выпить стакан водички\n31:12 Умывание\n32:23 Чистка зубов\n33:02 Чистка языка\n33:07 Чистка 9 отверстий\n36:05 Эзотерические метафоры для каждой чистки\n36:48 Омовение\n37:01 Выход на природу (хотя бы просто на улицу)\n37:48 Очищающее дыхание\n38:54 Выполнение асан или физических упражнений\n39:48 Медитация\n41:19 Об аффирмациях\n47:41 Наше тело как симбиотический организм\n58:17 Очищение рвотой и клизмой\n59:22 Чем опасна клизмотерапия\n01:00:22 Роль Шанк Пракшаланы (техника выполнения будет на следующем уроке)\n01:01:38 Голодание\n01:02:17 Правила здорового питания\n01:13:01 Однодневное голодание\n01:16:42 Трёхдневное голодание\n01:27:52 Пранаяма и Сурья Намаскар как очистительная практика\n01:28:27 Задание к уроку\n01:29:52 Ритуал посвящения заслуг\n\nОТВЕТЫ НА ВОПРОСЫ:"},{"type":"video","vimeoId":"1099992240"},{"type":"text","markdown":"ЗАДАНИЕ:\n1. Выполните утренние ритуалы, о которых я рассказал, чтобы закрепить знание. И с завтрашнего дня выполняйте их каждое утро.\n\n2. Выберите день на неделе, когда Вы сможете провести 24-часовое голодание. Поставьте намерение его провести (если нет противопоказаний)."}]'::jsonb,'2115100c-244b-520a-ae14-a9413fa6bf63') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('06a8574f-1995-5a45-bbcb-1c26b8b969ff','f4122683-07c0-518b-9102-9a066771750e','Урок 12: Специальные практики, возвращающие молодость тела',12,0,'{Йога и здоровье} Урок 12: Специальные практики, возвращающие молодость','{"ru":"{Йога и здоровье} Урок 12: Специальные практики, возвращающие молодость"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня на практическом уроке мы рассмотрим технику Шанк Пракшаланы, а также глубинные процессами, происходящими при её выполнении.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здровья и молодости!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня на практическом уроке мы рассмотрим технику Шанк Пракшаланы, а также глубинные процессами, происходящими при её выполнении.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здровья и молодости!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-12-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня на практическом уроке мы рассмотрим технику Шанк Пракшаланы, а также глубинные процессами, происходящими при её выполнении.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Здровья и молодости!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-12','yoga-health',12,1,'Урок 12: Специальные практики, возвращающие молодость тела','[{"type":"text","markdown":"В этом уроке мы рассмотрим тему старения. Точнее - омоложения :). И с этой целью мы  подробно изучим мощнейшую практику - Шанк Пракшалану, а также очистительные пранаямы. При этом мы под новым углом рассмотрим процессы, происходящие при оздоравливающем голодании."},{"type":"video","vimeoId":"1100119162"},{"type":"text","markdown":"Тайминг:\n02:55 Сколько лет нам \"отпущено\"\n03:30 Возрастные периоды жизни\n05:02 Суть кризиса среднего возраста\n06:56 Магические способности нашего тела\n10:43 Как вернуть молодость\n11:25 Надевайте маску молодости\n17:28 Используйте \"магию\" асан для омолаживания\n18:43 Мы выглядим старше своих лет если накопили много тамаса\n22:48 Очищение от старого на психическом уровне\n24:15 Физические чистки\n27:35 Почему голодание омолаживает\n35:21 Техника безопасности и нюансы выполнения Шанк Пракшаланы\n01:01:06 Упражения в составе Шанк Пракшаланы\n01:11:24 Шанк Пракшалана как очистительная пранаяма\n01:11:47 Пранаяма \"Ха\"\n01:17:24 Противопоказания для Шанк Пракшаланы\n01:22:18 Пранаяма \"Простукивание\"\n01:27:14 Полное йоговское дыхание как очистительная пранаяма\n01:28:56 Почему очистительные пранаямы особенно важны начинающим\n01:35:09 Очистительная функция болезней\n01:39:40 Какие негативные состояния бывают во время голодания\n01:41:06 Почему во время голодания возникают странные состояния\n01:41:54 Голодание обучает позиции \"наблюдателя\", и ощущениям психических энергий\n01:45:42 Задание к уроку\n\nЗАДАНИЕ:\n1. Закрепите технику Шанк Пракшаланы, выполнив её семь раз без питья воды.\n\n2. Если вы готовы и нет противопоказаний, то спланируйте в какой день вы можете провести Шанк Пракшалану, и поставьте намерение сделать это.\n\n3. Несколько раз выполните очистительные пранаямы, рассмотренные в данном уроке."}]'::jsonb,'06a8574f-1995-5a45-bbcb-1c26b8b969ff') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('b5f33e46-97fb-5443-b89f-489852ea54af','f4122683-07c0-518b-9102-9a066771750e','Урок 13: Управление потоками здоровья и благосостояния',13,0,'{Йога и здоровье} Урок 13: Управление потоками здоровья и благосостояния','{"ru":"{Йога и здоровье} Урок 13: Управление потоками здоровья и благосостояния"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Движение в потоке всех привлекает энергоэффективностью. Возможно ли двигаться в потоке муладхары? Как в него войти? Как удерживаться? Ответы на эти вопросы Вы узнаете, пройдя данный урок.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Движение в потоке всех привлекает энергоэффективностью. Возможно ли двигаться в потоке муладхары? Как в него войти? Как удерживаться? Ответы на эти вопросы Вы узнаете, пройдя данный урок.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-13-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Движение в потоке всех привлекает энергоэффективностью. Возможно ли двигаться в потоке муладхары? Как в него войти? Как удерживаться? Ответы на эти вопросы Вы узнаете, пройдя данный урок.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-13','yoga-health',13,3,'Урок 13: Управление потоками здоровья и благосостояния','[{"type":"text","markdown":"На предыдущих уроках мы создали глубокий и устойчивый психологический фундамент для того чтобы смотреть на окружающий мир глазами йоги. И сегодня мы готовы к тому, чтобы разобрать ключевую тему данного курса - здоровье и благосостояние. Мы рассмотри эзотерические законы, управляющие данными сферами, а также проведём медитацию, которая поможет Вам войти в поток оздоравливания."},{"type":"video","vimeoId":"1100530391"},{"type":"text","markdown":"Тайминг:\n03:46 Чем заняться в новолуние\n07:01 Ритуал приветствия и постановки намерения\n14:31 Онтогенез как ключ к доступным нам животным энергиям и здоровью\n17:27 Этимология слова \"здоровье\" и выводы из него\n19:43 Какие ещё бывают очистительные процедуры - чистка чакр, чистка от паразитов (чесночная диета), чистка от солей (рисовая диета), чистка печени, чистка гайморовых пазух, чистка кожи...\n24:53 Закон муладхары - заполняй своё пространство целиком\n26:12 Медитация на осознавание актуальных проблемных зон\n37:32 Как проявлятся поток оздоравливания\n39:09 Как понять, что поток закончился, и начался автоматизм\n40:51 Кто такая Баба Яга\n45:48 Пример затруднённого осознавания муладхарной потребности, и реакции тела на это\n51:40 Благосостояние, как аналог здоровья на социальном уровне\n54:27 Пример нарушения по муладхаре, которое привело к разрушению благосостояния\n59:08 О накладывании муладхарного поля на внешние объекты\n01:07:01 Отток на нижней чакре приводит к оттоку на верхних\n01:08:50 Как войти в поток благосостояния\n01:10:17 Пример роста благосостояния\n01:14:31 Отток благосостояния по причине не своевременного реагирования на проблему\n01:17:22 Отпустить проблему можно только полюбив её\n01:18:57 Метафора свастики в отношении муладхары\n01:20:24 Задание к уроку\n01:21:51 Посвящение заслуг\n\nЗАДАНИЯ:\n- Походите в гости, и почувствуйте своё место в пространстве муладхары\n\n- Составьте план выполнения действий, которые Вы наметили в медитации данного урока"}]'::jsonb,'b5f33e46-97fb-5443-b89f-489852ea54af') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('6787f9e8-a154-58c8-927d-8d181221a21d','f4122683-07c0-518b-9102-9a066771750e','Урок 14: Комплекс на раскрытие тазобедренных суставов',14,0,'{Йога и здоровье} Урок 14: Комплекс на раскрытие тазобедренных суставов','{"ru":"{Йога и здоровье} Урок 14: Комплекс на раскрытие тазобедренных суставов"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня мы освоим новый комплекс асан, а также применим на практике технику использования оздоравливающих метафор.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня мы освоим новый комплекс асан, а также применим на практике технику использования оздоравливающих метафор.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-14-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сегодня мы освоим новый комплекс асан, а также применим на практике технику использования оздоравливающих метафор.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-14','yoga-health',14,1,'Урок 14: Комплекс на раскрытие тазобедренных суставов','[{"type":"video","vimeoId":"1100119558"},{"type":"text","markdown":"Тайминг:\n04:50 Пробуждение организма\n11:45 Ставим энергетический поток\n12:57 Какие качества личности развивают разные типы асан\n14:37 Суставная гимнастика\n25:51 Несклько дополнительных потягушек\n33:35 Сурья Намаскар\n52:48 Вирабхадрасана (1, 2, 3 разновидность)\n01:16:19 Прасарита Падоттанасана\n01:19:05 Намаскарасана\n01:25:02 Расслабление между сетами асан\n01:29:58 Агни Стамбхасана\n01:36:25 Упавиштха Конасана\n01:44:45 Суть и техника пранаямы на примере позы широкого угла\n01:47:50 Обнимайте Землю для исцеления\n01:49:42 Супта Матсиендрасана\n02:01:28 Шавасана"}]'::jsonb,'6787f9e8-a154-58c8-927d-8d181221a21d') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('0e50f72d-a45c-518b-ba5d-e1fc8f4e9622','f4122683-07c0-518b-9102-9a066771750e','Урок 15: Встреча с нашей вирусной природой, и законы муладхары',15,0,'{Йога и здоровье} Урок 15: Выход из вирусной программы человечества, и законы муладхары','{"ru":"{Йога и здоровье} Урок 15: Выход из вирусной программы человечества, и законы муладхары"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Как настроение? Что Вы только что почувствовали, увидев моё письмо? Возможно, &quot;наконец-то&quot;, а может быть &quot;ну вот опять&quot;. Эмоции, которые мы обычно чувствуем по отношению к происходящим с нами событиям, являются голосом нашего бессознательного. Попробуйте прислушиваться к ним, и следовать их советам.</p><p></p><p>А сейчас Вас ждёт интереснейший урок - главном страхе человечества, и о чакральных законах.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Как настроение? Что Вы только что почувствовали, увидев моё письмо? Возможно, &quot;наконец-то&quot;, а может быть &quot;ну вот опять&quot;. Эмоции, которые мы обычно чувствуем по отношению к происходящим с нами событиям, являются голосом нашего бессознательного. Попробуйте прислушиваться к ним, и следовать их советам.</p><p></p><p>А сейчас Вас ждёт интереснейший урок - главном страхе человечества, и о чакральных законах.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-15-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Как настроение? Что Вы только что почувствовали, увидев моё письмо? Возможно, &quot;наконец-то&quot;, а может быть &quot;ну вот опять&quot;. Эмоции, которые мы обычно чувствуем по отношению к происходящим с нами событиям, являются голосом нашего бессознательного. Попробуйте прислушиваться к ним, и следовать их советам.</p><p></p><p>А сейчас Вас ждёт интереснейший урок - главном страхе человечества, и о чакральных законах.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-15','yoga-health',15,2,'Урок 15: Встреча с нашей вирусной природой, и законы муладхары','[{"type":"text","markdown":"В этом уроке мы рассмотрим ещё один способ определить свой вектор развития, получим опыт из главного страха человечества (медитация), разберёмся что такое чакральные законы, а также Вы получите экзаменационное задание :)"},{"type":"video","vimeoId":"1100119654"},{"type":"text","markdown":"Тайминг:\n02:22 Цель данного урока\n07:01 Приветствие пространства и постановка потока\n11:51 Ещё один способ определить свой вектор развития\n23:09 Где ваше место силы\n24:00 Как изменить место жительства\n26:14 Моменты бифуркации (свободы)\n36:39 Как выбрать своё питание (мясоед, вегетарианец...)\n46:52 Что даёт принятие своего тела\n51:02 Выход из под страхов человечества\n54:06 Почему мы не можем вспомнить свои прошлые жизни\n59:19 Бутылочное горлышко Homo Sapiens\n01:08:45 Идея \"духовного развития\" - опиум для народа?\n01:14:13 Медитация освобождения от страха\n01:32:48 Когда страх существует, а когда его нет\n01:37:05 Экзаменационное задание\n01:38:56 Что такое чакральные законы\n01:47:10 О принятии бытовых появлений Божественного\n01:53:03 Уточнения к заданию\n\nЭКЗАМЕНАЦИОННОЕ ЗАДАНИЕ:\n\nНиже в поле комментариев перечислите наиболее актуальные для Вас чакральные законы муладхары, которые Вы узнали, проходя данный курс."}]'::jsonb,'0e50f72d-a45c-518b-ba5d-e1fc8f4e9622') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('666ac3ed-1e2e-5d76-805f-da19f4eedfd1','f4122683-07c0-518b-9102-9a066771750e','Урок 16: Практика йоги в тонких телах, и одна асана изменяющая жизнь',16,0,'{Йога и здоровье} Урок 16: Практика йоги в тонких телах, и одна асана изменяющая жизнь','{"ru":"{Йога и здоровье} Урок 16: Практика йоги в тонких телах, и одна асана изменяющая жизнь"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Длинный курс позади. На первый взгляд, так много пройдено, с другой стороны, все гениальное - ПРОСТО. И сегодня мы подведем итог курса, и вернёмся к простоте.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Длинный курс позади. На первый взгляд, так много пройдено, с другой стороны, все гениальное - ПРОСТО. И сегодня мы подведем итог курса, и вернёмся к простоте.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-16-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Длинный курс позади. На первый взгляд, так много пройдено, с другой стороны, все гениальное - ПРОСТО. И сегодня мы подведем итог курса, и вернёмся к простоте.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-16','yoga-health',16,1,'Урок 16: Практика йоги в тонких телах, и одна асана изменяющая жизнь','[{"type":"text","markdown":"Хотя это и практический урок, но, прежде чем перейти к практике асан, на этом занятии мы резюмируем некоторые критически важные темы предыдущих уроков. В результате у вас не должно остаться никаких вопросов относительно выстраивания практики йоги на ближайшее время."},{"type":"video","vimeoId":"1100119731"},{"type":"text","markdown":"Тайминг:\n01:39 Устанавливайте связь с предметами силы\n04:11 Приветствие и постановка намерения\n09:53 Чакральный закон муладхары - у природы нет плохой погоды (всё нужно принимать)\n12:26 Движение как способ выйти из негативных состояний\n15:50 Намерение на практику должно отражать текущую ситуацию\n29:26 Метафора тонких тел в разных эзотерических традициях\n34:50 На уровне какого какого тела практиковать йогу\n41:17 Проработка в асанах разных уровней физического тела\n48:03 Если есть вопросы по технике выполнения асан\n52:29 О простоте в йоге. Почему одна лишь Тадасана может изменить жизнь\n01:06:37 Суставная гимнастика\n01:13:03 Комплекс из Тайчи - Очищение пяти элементов\n01:28:00 Сурья Намаскар\n01:58:00 Посвящение заслуг\n\nА теперь я предлагаю вам переместиться в старинный русский город Суздаль и посмотреть запись мастеркласса \"Как мягко войти в йогу и начать получать результаты сразу\". Этот мастеркласс дополняет материалы курса, поэтому будет вам интересен и полезен."},{"type":"video","vimeoId":"1248490304"}]'::jsonb,'666ac3ed-1e2e-5d76-805f-da19f4eedfd1') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('0a6d3c02-4663-52e7-94fe-8ea32b98570a','f4122683-07c0-518b-9102-9a066771750e','Урок 17: Практика НЕ-асан йоги',17,0,'{Йога и здоровье} Урок 17 (сюрприз)','{"ru":"{Йога и здоровье} Урок 17 (сюрприз)"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Прошла неделя после окончания курса, и размышляя над его результатами, я решил предложить Вам ещё один урок.</p><p></p><p>Я надеюсь, Вы сейчас ежедневно практикуете. И если так, то Вы наверняка заметили насколько слодно выполнять даже простейшие асаны. Например, для медитации Вы садитесь с прямой спиной, но через минуту замечаете, что плечи опустились, шея прогнулась, поясница округлилась... Волевым усилием Вы стараетесь контролировать все ключевые точки, но упускаете то одно, то другое, то третье... А через несколько минут у Вас начинает ломить спину, затекают ноги или даже руки, и Вы решаете выйти из асаны... Так что-же делать? Осмелюсь предположить, что тело хочет сказать Вам что-то очень важное :) И в данном видео я предлагаю интересную технику НЕ-асан :)</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Прошла неделя после окончания курса, и размышляя над его результатами, я решил предложить Вам ещё один урок.</p><p></p><p>Я надеюсь, Вы сейчас ежедневно практикуете. И если так, то Вы наверняка заметили насколько слодно выполнять даже простейшие асаны. Например, для медитации Вы садитесь с прямой спиной, но через минуту замечаете, что плечи опустились, шея прогнулась, поясница округлилась... Волевым усилием Вы стараетесь контролировать все ключевые точки, но упускаете то одно, то другое, то третье... А через несколько минут у Вас начинает ломить спину, затекают ноги или даже руки, и Вы решаете выйти из асаны... Так что-же делать? Осмелюсь предположить, что тело хочет сказать Вам что-то очень важное :) И в данном видео я предлагаю интересную технику НЕ-асан :)</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-17-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Прошла неделя после окончания курса, и размышляя над его результатами, я решил предложить Вам ещё один урок.</p><p></p><p>Я надеюсь, Вы сейчас ежедневно практикуете. И если так, то Вы наверняка заметили насколько слодно выполнять даже простейшие асаны. Например, для медитации Вы садитесь с прямой спиной, но через минуту замечаете, что плечи опустились, шея прогнулась, поясница округлилась... Волевым усилием Вы стараетесь контролировать все ключевые точки, но упускаете то одно, то другое, то третье... А через несколько минут у Вас начинает ломить спину, затекают ноги или даже руки, и Вы решаете выйти из асаны... Так что-же делать? Осмелюсь предположить, что тело хочет сказать Вам что-то очень важное :) И в данном видео я предлагаю интересную технику НЕ-асан :)</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Хорошего дня!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-17','yoga-health',17,7,'Урок 17: Практика НЕ-асан йоги','[{"type":"text","markdown":"Что делать, если асаны не удаются так как вам хочется? Сбросьте напряжение, и выполните то, что не просто получается, но что хочется вашему телу. После этого асаны начнут получаться лучше, и как-бы сами собой. Чтобы эта техника сработала как практика йоги, а не какая-то абстрактная гимнастика, необходим правильный настрой. Данный урок поможет вам разобраться и научиться практиковать НЕ-асаны."},{"type":"video","vimeoId":"1100119840"},{"type":"text","markdown":"Задание:\nВыполните эту практику ещё хотя-бы три раза в ближайшие три дня. В результате вы сделаете её \"своей\".\n\n+++++++++++++++++\n\nИ ещё...\n\nЧестно говоря, по своей глубине курс превзошёл мои ожидания. Если Вы можете сказать несколько слов в качестве видео-отзыва (рекомендации), который я опубликую на сайте, я буду Вам очень благодарен. Да и для людей будет польза, так как в интернете сейчас сложно отличать пустышки от чего-то содержательного. И отзывы помогают делать выбор.\n\nВидео-отзыв - это буквально несколько предложений общей длительностью 1-2 минуты. Просто, положите мобильник горизонтально (не вертикально) на стол в метре перед собой, поздоровайтесь, представьтесь, и скажите что Вам понравилось в курсе, чем он оказался Вам полезен, чем он особенный, почему его стоит пройти... Не фиксируйтесь на этих темах. Скажите ровно то, что хотите сказать. Эмоционально и правдиво. И, пожалуйста, говорите громко, чтобы было хорошо слышно. И сядьте так, чтобы Ваше лицо было освещено (то есть лампа или окно чтобы были спереди, а не сзади). В записи называйте курс не \"Новогодний\", а \"Йога и здоровье\" (новый год уже наступил, и в записи курса я его переименовал в соответствии с предметом). Отнеситесь к записи видео легко, играючи, и получите удовольствие :)\n\nНе монтируйте видео, я это сделаю сам. Просто, пришлите мне эту запись имейлом. Если при отправке записи возникнут проблемы, напишите, придумаем как их преодолеть.\n\nСпасибо!"}]'::jsonb,'0a6d3c02-4663-52e7-94fe-8ea32b98570a') on conflict(id) do nothing;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('d1d6535b-a811-503a-b862-13abac07d8a9','f4122683-07c0-518b-9102-9a066771750e','Урок 18: Практика исполнения желаний',18,0,'{Йога и здоровье} Практика исполнения желаний','{"ru":"{Йога и здоровье} Практика исполнения желаний"}'::jsonb,'<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png" alt="Йога и здоровье" width="504" height="192" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я решил дополнительно к курсу открыть вам доступ к записи практики, направленной на исполнение желаний уровня муладхары. Уверен, что она будет вам полезна и поможет практиковать йогу эффективней.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Исполнения желаний!<br>Сергей Замковой</p>','{"ru":"<div style=\"margin:0px 0 24px;text-align:center;\"><img src=\"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png\" alt=\"Йога и здоровье\" width=\"504\" height=\"192\" style=\"width:100%;max-width:100%;height:auto;display:inline-block;border:0;\" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я решил дополнительно к курсу открыть вам доступ к записи практики, направленной на исполнение желаний уровня муладхары. Уверен, что она будет вам полезна и поможет практиковать йогу эффективней.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Исполнения желаний!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"course-yoga-health-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/yoga-health/yoga-health_email-0d090e6ba078.png","alt":"Йога и здоровье","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":600,"naturalHeight":228},{"id":"yoga-health-18-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Я решил дополнительно к курсу открыть вам доступ к записи практики, направленной на исполнение желаний уровня муладхары. Уверен, что она будет вам полезна и поможет практиковать йогу эффективней.</p><p></p><p>Урок уже доступен вам во вкладке &quot;День&quot; Гармонизатора.</p><p></p><p>Исполнения желаний!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('yoga-health-18','yoga-health',18,3,'Урок 18: Практика исполнения желаний','[{"type":"text","markdown":"В новогодние праздники я провёл три практики йоги, направленные на исполнение желаний в трёх сферах: здоровье, деньги и любовь - то есть на уровне соответствующих чакр - муладхары, манипуры и анахаты. И сегодня я предлагаю вам выполнить практику, направленную на исполнение желаний, связанных со здоровьем - то есть исцелением заболеваний, улучшением осанки, нормализацией веса, выработкой привычек здорового образа жизни и т.п. Уверен, что она принесёт плоды не только в плане здоровья, но и в плане лучшего понимания эффективной практики йогой."},{"type":"video","vimeoId":"661894917"},{"type":"text","markdown":"Получить две другие практики исполнения желаний вы можете со скидкой. Перейдите по ссылке, чтобы узнать подробности.\n\n[Узнать подробности](https://zamkovoi.ru/3z2/)"}]'::jsonb,'d1d6535b-a811-503a-b862-13abac07d8a9') on conflict(id) do nothing;
